package com.app.service;
import com.app.dto.*;import com.app.dto.SocietyAttendanceDtos.AttendanceRow;import com.app.entity.*;import com.app.exception.*;import com.app.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class SocietyAttendanceSelfServiceService {private final SocietyStaffAccessRepository access;private final SocietyRosterAssignmentRepository roster;private final SocietyAttendanceRepository attendance;private final SocietyAuditEventRepository audit;private final SocietyAttendanceService attendanceService;
 @Transactional(readOnly=true) public List<AttendanceRow> mine(Long aid,Long uid){SocietyStaffAccess a=worker(aid,uid);Set<Long> own=roster.findByAccountIdAndActiveTrueOrderByPostNameAsc(aid).stream().filter(x->x.getStaff()!=null&&x.getStaff().getId().equals(a.getStaff().getId())).map(SocietyRosterAssignment::getId).collect(java.util.stream.Collectors.toSet());return attendanceService.day(aid,LocalDate.now()).stream().filter(x->own.contains(x.getRosterAssignmentId())).toList();}
 @Transactional public List<AttendanceRow> record(Long aid,Long uid,SocietyAttendanceSelfServiceRequest request){SocietyStaffAccess a=worker(aid,uid);LocalDate date=LocalDate.now();List<SocietyRosterAssignment> own=roster.findByAccountIdAndActiveTrueOrderByPostNameAsc(aid).stream().filter(x->x.getStaff()!=null&&x.getStaff().getId().equals(a.getStaff().getId())&&!date.isBefore(x.getEffectiveFrom())&&(x.getEffectiveTo()==null||!date.isAfter(x.getEffectiveTo()))).toList();if(own.size()!=1)throw new ValidationException("Self-service requires exactly one active roster assignment today");SocietyRosterAssignment r=own.get(0);SocietyAttendance row=attendance.findByRosterAssignmentIdAndAttendanceDate(r.getId(),date).orElseGet(()->SocietyAttendance.builder().account(a.getAccount()).rosterAssignment(r).attendanceDate(date).status("PRESENT").recordedBy(a.getUser()).build());LocalTime now=LocalTime.now().withSecond(0).withNano(0);if("CHECK_IN".equals(request.getAction())){if(row.getCheckIn()!=null)throw new ValidationException("Already checked in");row.setCheckIn(now);}else{if(row.getCheckIn()==null)throw new ValidationException("Check in first");if(row.getCheckOut()!=null)throw new ValidationException("Already checked out");row.setCheckOut(now);}row.setStatus("PRESENT");row.setRecordingMethod("STAFF_SELF_SERVICE");row.setRecordedBy(a.getUser());attendance.save(row);audit.save(SocietyAuditEvent.builder().account(a.getAccount()).actor(a.getUser()).action("ATTENDANCE_SELF_"+request.getAction()).entityType("ATTENDANCE").entityId(row.getId()).details("staffId="+a.getStaff().getId()).build());return mine(aid,uid);}
 private SocietyStaffAccess worker(Long aid,Long uid){SocietyStaffAccess a=access.findByAccountIdAndUserIdAndStatus(aid,uid,StaffAccessStatus.ACTIVE).orElseThrow(()->new ValidationException("Active staff access required"));if(a.getRole()!=UserRole.STAFF)throw new ValidationException("Worker self-service role required");return a;}
}
